function myParseInt ( value , dummyPrevious ) {
// parseInt takes a string and a radix
const parsedValue = parseInt ( value , 10 ) ;
if ( isNaN ( parsedValue ) ) {
throw new commander . InvalidArgumentError ( 'Not a number.' ) ;
}
return parsedValue ;
}

function increaseVerbosity ( dummyValue , previous ) {
return previous + 1 ;
}

function collect ( value , previous ) {
return previous . concat ( [ value ] ) ;
}

function commaSeparatedList ( value , dummyPrevious ) {
return value . split ( ',' ) ;
}

You can specify (sub)commands using .command() or .addCommand() . There are two ways these can be implemented: using an .action() handler attached to the command; or as a stand-alone executable file. (More detail about this later.) … // Command implemented using action handler (description is supplied separately to `.command`)
// Returns new command for configuring.
program
. command ( 'clone <source> [destination]' )
. description ( 'clone a repository into a newly created directory' )
. action ( ( source , destination ) => {
console . log ( 'clone command called' ) ;
} ) ; … // Command implemented using stand-alone executable file, indicated by adding description as second parameter to `.command`.
// Returns `this` for adding more commands.
program
. command ( 'start <service>' , 'start named service' )
. command ( 'stop [service]' , 'stop named service, or all if no name supplied' ) ;

program
. version ( '0.1.0' )
. argument ( '<username>' , 'user to login' )
. argument ( '[password]' , 'password for user, if required' , 'no password given' )
. action ( ( username , password ) => {
console . log ( 'username:' , username ) ;
console . log ( 'password:' , password ) ;
} ) ;

